{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Fenspiride absolute oral bioavailability was 90% in healthy volunteers after an 80 mg slow-release tablet versus IV, showing that a small spiro-containing drug can be almost completely absorbed with negligible first-pass loss.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Hexobarbital absolute oral bioavailability in humans was 90%, supporting high oral absorption for a lipophilic, non-ionizable small molecule without obvious conjugation handles.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Aminoglutethimide oral bioavailability was approximately 100% in patients at 250-1000 mg/day, demonstrating that a lipophilic, neutral small molecule can have essentially complete oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Ursodeoxycholic acid, a steroid, had 50% systemic availability in normal subjects after oral versus IV dosing; despite polar hydroxyl and carboxyl groups, F is well above 20%, and the more lipophilic query steroid is expected to be at least as well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Pentazocine absolute bioavailability was 14.6% in a healthy subject, below the 20% threshold; however, this low F is driven by phenolic glucuronidation and first-pass metabolism of its basic benzomorphan structure, features absent in the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a lipophilic steroidal spiro-lactone with no ionizable groups or obvious conjugative soft spots. High-F analogues—including a steroid (UDCA, 50%), lipophilic neutral drugs (hexobarbital 90%, aminoglutethimide ~100%), and a spiro-containing drug (fenspiride 90%)—support high oral bioavailability. The only low-F analogue (pentazocine) has phenolic/basic-amine first-pass liabilities absent in the query. Therefore F ≥20% is strongly supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is present in the provided evidence.",
    "No human PK study with an IV comparator for drospirenone or the exact query structure is included.",
    "Formulation-dependent solubility or absorption effects are not directly assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

